(()=>{
 const D=RoadmapData,key='statics-roadmap-v1';let topic='resultants',saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}if(typeof saved!=='object'||Array.isArray(saved))saved={};
 const persist=()=>{try{localStorage.setItem(key,JSON.stringify(saved));}catch{}},progress=p=>{if(!saved[p.id]||typeof saved[p.id]!=='object')saved[p.id]={index:0,answers:{},checked:{},helped:{}};const v=saved[p.id];for(const name of ['answers','checked','helped'])if(!v[name]||typeof v[name]!=='object')v[name]={};v.index=Math.max(0,Math.min(p.steps.length-1,Math.floor(Number(v.index))||0));return v;};
 function draw(p){const svg=$('roadmapDiagram');if(!svg||!p.diagram)return;const origin=[100,430],scale=65,screen=v=>[origin[0]+v[0]*scale,origin[1]-v[1]*scale];let out='<rect width="600" height="400" fill="#141b24"/>'+GraphScales.axesSVG('xy',screen,6,p.diagram==='coordinates'?'m':'N',500);if(p.diagram==='coordinates'){for(const [label,v,color] of [['A',[1,1,0],'#8cbcff'],['B',[4,5,0],'#efbd77']]){const q=screen(v);out+=`<path d="M${q[0]} ${origin[1]}V${q[1]}H${origin[0]}" stroke="${color}" stroke-dasharray="4 5" fill="none"/><circle cx="${q[0]}" cy="${q[1]}" r="6" fill="${color}"/><text x="${q[0]+12}" y="${q[1]-10}" font-size="17" fill="${color}">${label}</text>`;}}else{out='<rect width="600" height="400" fill="#141b24"/>'+GraphScales.axesSVG('xy',v=>[300+v[0],290-v[1]],160,'N');for(const [label,mag,angle,color] of [['A',120,30,'#8cbcff'],['B',90,120,'#efbd77']])out+=`<line x1="300" y1="290" x2="${300+mag*Math.cos(angle*Math.PI/180)}" y2="${290-mag*Math.sin(angle*Math.PI/180)}" stroke="${color}" stroke-width="4"/><text x="${315+mag*Math.cos(angle*Math.PI/180)}" y="${280-mag*Math.sin(angle*Math.PI/180)}" fill="${color}" font-size="17">${label}</text>`;out+=GraphScales.planarAngle([300,290],30,32,'α = 30°','#8cbcff')+GraphScales.planarAngle([300,290],120,60,'β = 120°','#efbd77');}GraphScales.paint(svg,out);}
 function formula(s){const title=s.title.toLowerCase(),norm=v=>mo('|')+v+mo('|'),rv=vector('r','rvector'),fv=vector('F','Fvector');let body='';if(title.includes('normalize'))body=vector('u','uvector')+mo('=')+fraction(rv,norm(rv));else if(title==='build the direction vector')body=taggedVector('r','AB','displacement')+mo('=')+taggedVector('r','B','positionB')+mo('−')+taggedVector('r','A','positionA');else if(title==='construct the cable force')body=fv+mo('=')+mi('F')+taggedVector('u','AB','unitAB');else if(title==='add matching components')body=sub('R','x')+mo('=')+sub('A','x')+mo('+')+sub('B','x')+mo(',')+sub('R','y')+mo('=')+sub('A','y')+mo('+')+sub('B','y');else if(title==='take the scalar projection')body=sub('F','axis')+mo('=')+fv+mo('·')+taggedVector('u','AB','unitAB');else if(title==='project the moment')body=mi('M','axisMomentScalar')+mo('=')+vector('u','axisMomentUnit')+mo('·')+vector('M','axisPointMoment');else if(title.includes('calculate the moment')||title==='calculate the point moment')body=vector('M','momentVector')+mo('=')+vector('r','momentPosition')+mo('×')+vector('F','forceMoment');else if(title==='find the perpendicular arm'||title==='find the perpendicular spacing')body=mi('d',title.includes('spacing')?'coupleArm':'momentArm')+mo('=')+fraction(norm(vector('M',title.includes('spacing')?'coupleVector':'momentVector')),norm(fv));return body?'<div class="math">'+math(body)+'</div>':'';}
 function history(p,state){const completed=p.steps.map((s,i)=>({s,i,answers:state.answers[i]||{}})).filter(({s,i,answers})=>i!==state.index&&state.checked[i]&&D.correct(s,answers));if(!completed.length)return '';return `<article class="panel roadmap-history"><h2>Your checked steps</h2><p class="projection-note">Keep these results beside the current step. Values below are the answers you entered; open a row for the full explanation.</p>${completed.map(({s,i,answers})=>`<details class="history-step"><summary><strong>${i+1}. ${s.title}</strong><span>${s.options?M.esc(s.options[Number(answers.choice)]):s.fields.map((f,j)=>`<b>${M.esc(f.label)}</b> = ${M.esc(answers[j])}`).join(' · ')}${state.helped[i]?' · explanation viewed':''}</span></summary><p>${s.why}</p>${formula(s)}<p>${s.solution}</p><button data-roadmap-step="${i}">Return to step ${i+1}</button></details>`).join('')}</article>`;}
 function render(){const p=D.problems.find(p=>p.id===topic),state=progress(p),s=p.steps[state.index],answers=state.answers[state.index]||{},passed=!!state.checked[state.index]&&D.correct(s,answers);$('roadmap').innerHTML=`<div class="roadmap-topic"><div><article class="panel"><div class="eyebrow">GUIDED PROBLEM · ${p.title}</div><h2>${p.title}: build the solution</h2><p class="position-problem">${p.prompt}</p>${p.diagram?'<svg id="roadmapDiagram" viewBox="0 0 600 500" role="img" aria-label="Problem geometry with labelled coordinate axes"></svg>':''}<div class="roadmap-step-map">${p.steps.map((step,i)=>`<button data-roadmap-step="${i}" ${i>0&&!p.steps.slice(0,i).every((s,j)=>state.checked[j]&&D.correct(s,state.answers[j]||{}))?'disabled':''} aria-current="${i===state.index?'step':'false'}">${state.checked[i]?'✓ ':''}${i+1}. ${step.title}</button>`).join('')}</div><p class="projection-note">Original worked practice. Answers and progress save in this browser only. You may return to earlier steps.</p></article><div id="roadmapHistory">${history(p,state)}</div><article class="panel roadmap-question"><div class="eyebrow">STEP ${state.index+1} / ${p.steps.length}</div><h2>${s.title}</h2><div class="insight"><strong>Why this step?</strong><p>${s.why}</p></div>${formula(s)}<p class="assessment-prompt">${s.question}</p>${s.options?`<fieldset class="answer-options"><legend>Choose an answer</legend>${s.options.map((option,i)=>`<label class="answer-option"><input type="radio" name="roadmapChoice" value="${i}" ${Number(answers.choice)===i&&answers.choice!==undefined?'checked':''}><span>${option}</span></label>`).join('')}</fieldset>`:`<div class="position-answer-grid">${s.fields.map((f,i)=>`<label>${f.label}<input data-roadmap-field="${i}" type="number" step="any" value="${M.esc(answers[i]??'')}"></label>`).join('')}</div><p class="projection-note">Accepted tolerance: ${s.fields.map(f=>`${f.label}: ±${f.tolerance}`).join('; ')}.</p>`}<div class="actions"><button id="roadmapCheck" class="primary">Check this step</button><button id="roadmapExplain">Show worked explanation</button><button id="roadmapNext" ${passed?'':'disabled'}>${state.index===p.steps.length-1?'Complete problem':'Next step →'}</button></div><div id="roadmapFeedback" role="status">${passed?`<div class="assessment-feedback correct"><strong>Correct${state.helped[state.index]?' · with explanation viewed':''}.</strong><p>${s.solution}</p></div>`:''}</div><div id="roadmapSolution" class="assessment-feedback" hidden></div><div id="roadmapComplete" hidden class="insight"></div><div class="actions roadmap-bottom"><button id="roadmapExplore">Explore this topic in Workspace →</button><button id="roadmapRestart">Restart this walkthrough</button></div></article></div></div>`;
  const saveAnswer=(i,value)=>{state.answers[state.index]??={};state.answers[state.index][i]=value;delete state.checked[state.index];for(let j=state.index+1;j<p.steps.length;j++)delete state.checked[j];$('roadmapNext').disabled=true;$('roadmapFeedback').innerHTML='';$('roadmapHistory').innerHTML=history(p,state);document.querySelectorAll('[data-roadmap-step]').forEach(button=>button.onclick=()=>{const next=Number(button.dataset.roadmapStep);if(!p.steps.slice(0,next).every((step,i)=>state.checked[i]&&D.correct(step,state.answers[i]||{})))return;state.index=next;persist();render();});persist();};document.querySelectorAll('[data-roadmap-field]').forEach(input=>input.oninput=()=>saveAnswer(input.dataset.roadmapField,input.value));document.querySelectorAll('input[name="roadmapChoice"]').forEach(input=>input.onchange=()=>saveAnswer('choice',Number(input.value)));
  $('roadmapCheck').onclick=()=>{if(D.correct(s,state.answers[state.index]||{})){state.checked[state.index]=true;persist();render();}else{$('roadmapFeedback').innerHTML=`<div class="assessment-feedback incorrect"><strong>Review this step.</strong><p>Fill in every requested value, including zeros. Keep signs and units consistent.</p><p>${s.why}</p></div>`;}};
  $('roadmapExplain').onclick=()=>{state.helped[state.index]=true;persist();$('roadmapSolution').hidden=false;$('roadmapSolution').textContent=s.solution;};$('roadmapNext').onclick=()=>{if(!D.correct(s,state.answers[state.index]||{})||!state.checked[state.index])return;if(state.index<p.steps.length-1){state.index++;persist();render();}else{$('roadmapComplete').hidden=false;$('roadmapComplete').textContent='Walkthrough complete. You checked every step'+(Object.values(state.helped).some(Boolean)?' with worked explanations available.':'.')+' Try the Workspace or a timed exam to apply the process independently.';}};
  $('roadmapRestart').onclick=()=>{delete saved[topic];persist();render();};$('roadmapExplore').onclick=()=>{showView(p.workspace);};document.querySelectorAll('[data-roadmap-topic]').forEach(button=>button.onclick=()=>open(button.dataset.roadmapTopic));document.querySelectorAll('[data-roadmap-step]').forEach(button=>button.onclick=()=>{const next=Number(button.dataset.roadmapStep);if(!p.steps.slice(0,next).every((step,i)=>state.checked[i]&&D.correct(step,state.answers[i]||{})))return;state.index=next;persist();render();});draw(p);
 }
 function pTitle(id){return D.problems.find(p=>p.id===id).title+' walkthrough';}
 function open(id){if(window.examInProgress)return;if(!D.problems.some(p=>p.id===id))return;topic=id;showView('roadmap');render();$('pageTitle').textContent=pTitle(id);$('pageDescription').textContent=D.problems.find(p=>p.id===id).description;$('pageCategory').textContent='MIDTERM ROADMAP / '+pTitle(id).toUpperCase();document.title=pTitle(id)+' | Statics Study Lab';document.querySelectorAll('nav [data-roadmap-topic]').forEach(b=>{const active=b.dataset.roadmapTopic===id;b.setAttribute('aria-current',active?'page':'false');b.classList?.toggle('active',active);});if($('roadmapFolder'))$('roadmapFolder').open=true;}
 window.GuidedRoadmap={open,render};render();
})();
